create extension if not exists pgcrypto;
create table if not exists public.admin_profiles (id uuid primary key references auth.users(id) on delete cascade, email text unique not null, created_at timestamptz not null default now());
create table if not exists public.committees (id uuid primary key default gen_random_uuid(), name text not null, full_name text not null, slug text unique not null, abbreviation text, description text not null default '', theme text, agenda_description text, historical_context text, scope_of_discussion text, key_issues text, image_url text, background_guide_document_id uuid, is_visible boolean not null default true, is_published boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.documents (id uuid primary key default gen_random_uuid(), title text not null, description text not null default '', category text not null, storage_path text not null, file_type text not null default 'application/pdf', file_size bigint, committee_id uuid references public.committees(id) on delete set null, is_visible boolean not null default true, is_published boolean not null default false, uploaded_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.committees add constraint committees_guide_fk foreign key (background_guide_document_id) references public.documents(id) on delete set null;
create table if not exists public.announcements (id uuid primary key default gen_random_uuid(), title text not null, description text not null, image_url text, external_url text, published_at timestamptz, is_visible boolean not null default true, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(), title text not null, slug text unique not null, description text not null default '', image_url text, start_date timestamptz, end_date timestamptz, registration_url text, status text not null default 'scheduled', is_visible boolean not null default true, is_published boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.schedule_entries (id uuid primary key default gen_random_uuid(), title text not null, description text not null default '', event_date date not null, start_time time, end_time time, location text, display_order integer not null default 0, is_visible boolean not null default true, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.secretariat_members (id uuid primary key default gen_random_uuid(), name text not null, designation text not null, photograph_url text, biography text, contact_information text, display_order integer not null default 0, is_visible boolean not null default true, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.website_settings (id integer primary key default 1 check(id=1), conference_name text not null default 'Stella Maris Model United Nations', conference_year integer not null default 2027, conference_start_date date not null default '2027-01-29', conference_end_date date not null default '2027-01-30', venue text not null default 'Stella Maris College', city text not null default 'Chennai, India', timezone text not null default 'Asia/Kolkata', hero_title text not null default 'STELLA MARIS', hero_subtitle text not null default 'Where Ideas Become History.', hero_image_url text, about_content text not null default 'Conference information will be announced soon.', contact_email text, social_links jsonb not null default '{}', registration_url text, registration_message text not null default 'Registration details will be announced shortly.', registration_button_text text not null default 'Register Now', countdown_enabled boolean not null default true, updated_at timestamptz not null default now());
create table if not exists public.section_visibility (section_key text primary key, is_enabled boolean not null default true, updated_at timestamptz not null default now());
insert into public.committees(name,full_name,slug,abbreviation,description,display_order,is_published) values
