('UNHRC','United Nations Human Rights Council','unhrc','UNHRC','Committee agenda to be announced.',6,true) on conflict(slug) do nothing;
insert into public.website_settings(id) values(1) on conflict(id) do nothing;
insert into public.section_visibility(section_key) values ('about'),('committees'),('schedule'),('events'),('lightning_rounds'),('announcements'),('registration_popup'),('countdown'),('resources'),('secretariat'),('contact') on conflict(section_key) do nothing;
create index if not exists committees_public_idx on public.committees(is_published,is_visible,display_order);
create index if not exists documents_committee_idx on public.documents(committee_id);
create index if not exists events_public_idx on public.events(is_published,is_visible,display_order);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_profiles where id=auth.uid()); $$;
alter table public.admin_profiles enable row level security;
alter table public.committees enable row level security; alter table public.documents enable row level security; alter table public.announcements enable row level security; alter table public.events enable row level security; alter table public.schedule_entries enable row level security; alter table public.secretariat_members enable row level security; alter table public.website_settings enable row level security; alter table public.section_visibility enable row level security;
create policy "public reads published committees" on public.committees for select using ((is_published and is_visible) or public.is_admin());
create policy "admin manages committees" on public.committees for all using (public.is_admin()) with check (public.is_admin());
create policy "public reads published documents" on public.documents for select using ((is_published and is_visible) or public.is_admin()); create policy "admin manages documents" on public.documents for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads published announcements" on public.announcements for select using ((is_published and is_visible) or public.is_admin()); create policy "admin manages announcements" on public.announcements for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads published events" on public.events for select using ((is_published and is_visible) or public.is_admin()); create policy "admin manages events" on public.events for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads published schedule" on public.schedule_entries for select using ((is_published and is_visible) or public.is_admin()); create policy "admin manages schedule" on public.schedule_entries for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads published team" on public.secretariat_members for select using ((is_published and is_visible) or public.is_admin()); create policy "admin manages team" on public.secretariat_members for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads settings" on public.website_settings for select using(true); create policy "admin manages settings" on public.website_settings for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads section flags" on public.section_visibility for select using(true); create policy "admin manages sections" on public.section_visibility for all using(public.is_admin()) with check(public.is_admin());
create policy "admins read profile" on public.admin_profiles for select using(id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('committee-images','committee-images',true,5242880,array['image/jpeg','image/png','image/webp']),('background-guides','background-guides',false,15728640,array['application/pdf']),('website-assets','website-assets',true,5242880,array['image/jpeg','image/png','image/webp']),('secretariat-images','secretariat-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
update storage.buckets set public=false where id='background-guides';
create policy "public reads public images and published guides" on storage.objects for select using (bucket_id in ('committee-images','website-assets','secretariat-images') or (bucket_id='background-guides' and exists(select 1 from public.documents d where d.storage_path=name and d.is_published and d.is_visible)) or public.is_admin());
create policy "admin uploads assets" on storage.objects for insert with check (public.is_admin() and bucket_id in ('committee-images','background-guides','website-assets','secretariat-images'));
create policy "admin updates assets" on storage.objects for update using (public.is_admin()) with check (public.is_admin());
create policy "admin deletes assets" on storage.objects for delete using (public.is_admin());
